#include <stdio.h>

int lastRemaining(int n) {
    long long head = 1, step = 1;
    int left = 1;
    while (n > 1) {
        if (left || n % 2 == 1) head += step;
        n /= 2;
        step *= 2;
        left = !left;
    }
    return (int)head;
}

